{
  "design": {
    "theme": "crayon",
    "picture_style": "illustration"
  },
  "flow": [
    {"slide": 1, "does": "Recall sharing fairly", "look_at": {"kind": "picture", "shows": "Six apples ready to share between two children"}, "teaches": []},
    {"slide": 2, "does": "Introduce the approved objectives", "look_at": {"kind": "none", "shows": null}, "teaches": []},
    {"slide": 3, "does": "Teach halves and quarters of shapes", "look_at": {"kind": "diagram", "shows": "One shaded part out of two or four equal parts"}, "teaches": [1]},
    {"slide": 4, "does": "Check the equal-parts misconception", "look_at": {"kind": "diagram", "shows": "Two rectangles with equal and unequal divisions"}, "teaches": [1]},
    {"slide": 5, "does": "Model finding half of eight", "look_at": {"kind": "diagram", "shows": "Eight counters shared into two equal groups"}, "teaches": [2]},
    {"slide": 6, "does": "Try finding half of ten", "look_at": {"kind": "diagram", "shows": "Ten counters in two equal groups without counts"}, "teaches": [2]},
    {"slide": 7, "does": "Model finding quarter of twelve", "look_at": {"kind": "diagram", "shows": "Twelve counters shared into four equal groups"}, "teaches": [3]},
    {"slide": 8, "does": "Try finding quarter of sixteen", "look_at": {"kind": "diagram", "shows": "Sixteen counters in four equal groups without counts"}, "teaches": [3]},
    {"slide": 9, "does": "Check which sharing method finds a quarter", "look_at": {"kind": "none", "shows": null}, "teaches": [3]},
    {"slide": 10, "does": "Identify fractions in differently divided shapes", "look_at": {"kind": "diagram", "shows": "Two differently divided shapes with one part shaded"}, "teaches": [1]},
    {"slide": 11, "does": "Practise finding halves and quarters independently", "look_at": {"kind": "none", "shows": null}, "teaches": [2, 3]},
    {"slide": 12, "does": "Apply sharing to new situations, then complete the worksheet exit ticket", "look_at": {"kind": "none", "shows": null}, "teaches": [2, 3]}
  ],
  "title": {
    "template": "title",
    "heading": "Halves and quarters",
    "lead": "Share fairly: how many apples will each child get?",
    "picture": {
      "shows": "Six separate apples between two children",
      "must_see": ["six separate apples", "two waiting children"],
      "subject": "generic"
    }
  },
  "slides": [
    {
      "template": "visual-text",
      "heading": "Equal parts",
      "lead": "Equal parts are the same size.",
      "points": [
        {"label": "One half", "text": "One of two equal parts."},
        {"label": "One quarter", "text": "One of four equal parts."}
      ],
      "figure": {
        "kind": "fraction-shapes",
        "shows": "A half and a quarter of matching rectangles",
        "alt": "Two matching rectangles: one has one of two equal parts shaded; the other has one of four equal parts shaded.",
        "title": null,
        "shapes": [
          {"shape": "rectangle", "parts": 2, "cut": "vertical", "shaded": 1, "name": "½"},
          {"shape": "rectangle", "parts": 4, "cut": "grid", "shaded": 1, "name": "¼"}
        ]
      }
    },
    {
      "template": "big-visual",
      "heading": "Look carefully",
      "lead": "Which shaded part is one half? Explain why.",
      "figure": {
        "kind": "labelled-diagram",
        "shows": "Two identical rectangles side by side. A is divided vertically into two equal parts with the left part shaded. B is divided vertically into two unequal parts, one narrow and one wide, with the narrow part shaded. Do not label either as correct.",
        "labels": ["A", "B"]
      }
    },
    {
      "template": "steps",
      "heading": "Find one half of 8",
      "points": [
        "Start with 8 counters.",
        "Share into 2 equal groups.",
        "Count one group: half of 8 is 4."
      ],
      "figure": {
        "kind": "equal-groups",
        "shows": "Eight counters shared equally between two rings",
        "alt": "Eight counters shared into two equal groups of four.",
        "title": null,
        "total": 8,
        "groups": 2,
        "layout": "rings",
        "show_count": "each",
        "unknown": false
      }
    },
    {
      "template": "big-visual",
      "heading": "Your turn",
      "lead": "Find one half of 10. Count one group.",
      "figure": {
        "kind": "equal-groups",
        "shows": "Ten counters shared into two rings, with group counts unknown",
        "alt": "Ten counters shared equally between two rings. Find the number in one ring.",
        "title": null,
        "total": 10,
        "groups": 2,
        "layout": "rings",
        "show_count": "each",
        "unknown": true
      }
    },
    {
      "template": "steps",
      "heading": "Find one quarter of 12",
      "points": [
        "Start with 12 counters.",
        "Share into 4 equal groups.",
        "Count one group: a quarter of 12 is 3."
      ],
      "figure": {
        "kind": "equal-groups",
        "shows": "Twelve counters shared equally between four rings",
        "alt": "Twelve counters shared into four equal groups of three.",
        "title": null,
        "total": 12,
        "groups": 4,
        "layout": "rings",
        "show_count": "each",
        "unknown": false
      }
    },
    {
      "template": "big-visual",
      "heading": "Your turn",
      "lead": "Find one quarter of 16. Count one group.",
      "figure": {
        "kind": "equal-groups",
        "shows": "Sixteen counters shared into four rings, with group counts unknown",
        "alt": "Sixteen counters shared equally between four rings. Find the number in one ring.",
        "title": null,
        "total": 16,
        "groups": 4,
        "layout": "rings",
        "show_count": "each",
        "unknown": true
      }
    },
    {
      "template": "hinge",
      "heading": "Choose the method",
      "stem": "How do you find one quarter of 8 counters?",
      "options": [
        "Make 2 equal groups; count one.",
        "Make 4 equal groups; count one.",
        "Make 4 equal groups; count all."
      ],
      "correct": 2
    },
    {
      "template": "big-visual",
      "heading": "Name the shaded parts",
      "lead": "Name the shaded fraction in A and B. Explain how you know.",
      "figure": {
        "kind": "fraction-shapes",
        "shows": "A diagonally divided square and a horizontally divided rectangle",
        "alt": "A is a square with one of two equal triangles shaded. B is a rectangle with one of four equal horizontal strips shaded.",
        "title": null,
        "shapes": [
          {"shape": "square", "parts": 2, "cut": "diagonal", "shaded": 1, "name": "A"},
          {"shape": "rectangle", "parts": 4, "cut": "horizontal", "shaded": 1, "name": "B"}
        ]
      }
    },
    {
      "template": "practice",
      "heading": "Draw and share",
      "questions": [
        "Find one half of 18 counters.",
        "Find one quarter of 8 counters.",
        "Find one quarter of 20 counters."
      ],
      "instruction": "Draw equal groups. Write each answer.",
      "picture": null
    },
    {
      "template": "practice",
      "heading": "Use your learning",
      "questions": [
        "Half of 14 birds fly away. How many stay?",
        "Share 12 buns fairly on 4 plates. How many per plate?",
        "Stretch: find half and a quarter of 16. Which is more?"
      ],
      "instruction": "Draw your sharing. Explain your answers.",
      "picture": null
    }
  ]
}
